package com.nook.widgets;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;

public final class StockLibraryActivity extends Activity {
    private String brand;private boolean liquid;private LinearLayout content;
    @Override public void onCreate(Bundle state){super.onCreate(state);brand=getIntent().getStringExtra("brand");if(brand==null)brand="Apple";liquid=getIntent().getBooleanExtra("liquid",brand.equals("Apple")||brand.equals("macOS"));LinearLayout root=Ui.column(this);root.setBackgroundColor(Ui.BG);setContentView(root);Ui.insets(this,root);LinearLayout header=Ui.row(this);Ui.pad(header,16,10);header.addView(Ui.iconButton(this,"back","Go back",this::finish));Ui.weight(header,Ui.bold(this,brand+" stock families",22,Ui.TEXT));root.addView(header);ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));content=Ui.column(this);Ui.pad(content,24,20);scroll.addView(content);draw();}
    private void draw(){content.removeAllViews();List<StockCatalog.Family> families=StockCatalog.families(brand);int count=0;for(StockCatalog.Family f:families)count+=StockCatalog.presets(f).size();content.addView(Ui.bold(this,families.size()+" families · "+count+" Nook layouts",27,Ui.TEXT));Ui.gap(content,12);content.addView(Ui.text(this,"Choose a family, layout and size. Every card identifies its source: Android/Nook data, your own log, a connected feed, or an app shortcut. Original stock availability varies by OS, region and installed apps.",14,Ui.MUTED));Ui.gap(content,16);Switch glass=new Switch(this);glass.setText("Liquid Glass appearance");glass.setTextColor(Ui.TEXT);glass.setChecked(liquid);content.addView(glass);glass.setOnCheckedChangeListener((button,on)->liquid=on);Ui.gap(content,20);
        for(StockCatalog.Family family:families){LinearLayout card=Ui.column(this);Ui.pad(card,16,16);Ui.surface(card,Ui.SURFACE,20);card.addView(Ui.bold(this,family.title(),18,Ui.TEXT));Ui.gap(card,5);card.addView(Ui.text(this,family.source()+" · "+StockCatalog.presets(family).size()+" layouts",12,Ui.ACCENT));Ui.gap(card,7);card.addView(Ui.text(this,family.detail(),12,Ui.MUTED));Ui.gap(card,10);card.addView(Ui.button(this,"Browse layouts",Ui.BG,Ui.ACCENT,()->family(family)));content.addView(card);Ui.gap(content,14);}}
    private void family(StockCatalog.Family family){List<StockCatalog.Preset> presets=StockCatalog.presets(family);LinearLayout panel=Ui.column(this);Ui.pad(panel,18,12);panel.addView(Ui.text(this,family.source()+"\n"+family.detail(),13,Ui.MUTED));Ui.gap(panel,12);Spinner picker=new Spinner(this);String[] names=new String[presets.size()];for(int n=0;n<names.length;n++){StockCatalog.Preset p=presets.get(n);names[n]=p.layout()+" · "+p.size();}picker.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));panel.addView(picker);FrameLayout preview=new FrameLayout(this);preview.setBackgroundResource(R.drawable.preview_wallpaper);LinearLayout.LayoutParams previewSize=new LinearLayout.LayoutParams(-1,Ui.dp(this,290));panel.addView(preview,previewSize);Ui.gap(panel,10);panel.addView(Ui.text(this,"Preview uses a sample wallpaper. Configure your own data before adding. Your Android launcher controls the actual grid size; resize after placement when needed.",12,Ui.MUTED));Runnable show=()->{StockCatalog.Preset p=presets.get(picker.getSelectedItemPosition());JSONObject config=StockCatalog.configuration(p);ExtraData.put(config,"style",liquid?3:0);ExtraData.put(config,"_width",p.width());ExtraData.put(config,"_height",p.height());preview.removeAllViews();View v=Widgets.render(this,-1,p.family().kind(),config,false,true).apply(this,preview);int screenWidth=getResources().getDisplayMetrics().widthPixels-Ui.dp(this,84),w=Math.min(screenWidth,Ui.dp(this,p.width()));int h=Math.min(Ui.dp(this,320),Ui.dp(this,p.height()));FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(w,h,Gravity.CENTER);preview.getLayoutParams().height=h+Ui.dp(this,28);preview.requestLayout();preview.addView(v,params);};picker.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){show.run();}});ScrollView scroll=new ScrollView(this);scroll.addView(panel);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(family.title()).setView(scroll).setPositiveButton("Customize and add",(d,n)->{StockCatalog.Preset p=presets.get(picker.getSelectedItemPosition());startActivity(new Intent(this,WidgetConfigActivity.class).putExtra("kind",p.family().kind()).putExtra("preset",p.id()).putExtra("surface",liquid?3:0));}).setNegativeButton("Close",null).create();dialog.show();show.run();}
}
